import { PlaneGeometry, Mesh, Group, Vector3 } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';

const createNode = (config, ctx) => {
  // Load texture from atlas region (source rect 0,0,512,320)
  const texture = ctx.textureLoader.load(config.assets.imageUrl);
  // Assume texture is exactly 512x320, no offset needed
  texture.needsUpdate = true;

  // Plane geometry sized to atlas aspect ratio (512/320 = 1.6)
  const width = 0.5; // scene units, matches scale 1
  const height = width / (512 / 320);
  const geometry = new PlaneGeometry(width, height);

  // MeshBasicNodeMaterial with map node
  const material = new MeshBasicNodeMaterial();
  material.map = texture;
  material.transparent = true;

  // Sprite mesh (plane)
  const sprite = new Mesh(geometry, material);

  // Text content: "Collection 1" – headline using Lora serif, 0.34 scene-unit height
  const textMesh = ctx.fontAtlas.createText('Collection 1', {
    font: 'Lora',
    fontSize: 0.34,
    fontWeight: 400,
    color: '#e8ecf2' // paper color
  });
  // Position text slightly in front of sprite (z-offset)
  textMesh.position.z = 0.001;

  // Group to contain both sprite and text
  const group = new Group();
  group.add(sprite);
  group.add(textMesh);

  // Apply scene placement
  group.position.set(-3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Billboard: face camera each frame
  group.onBeforeRender = (renderer, scene, camera) => {
    const worldPos = new Vector3();
    group.getWorldPosition(worldPos);
    group.lookAt(camera.position.x, camera.position.y, camera.position.z);
  };

  // Cleanup resources
  group.userData.cleanup = () => {
    texture.dispose();
    geometry.dispose();
    material.dispose();
    if (textMesh.material) textMesh.material.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();
    // No GSAP timelines to kill
  };

  return group;
};

export default createNode;
